"""Pydantic models describing the ``spec`` of each custom resource.

These models are the single source of truth for both:

* runtime parsing/validation in the resource handlers (``resources/*.py``), and
* the CustomResourceDefinition ``openAPIV3Schema`` generated by
  ``scripts/gen_crds.py`` into ``chart/airflow-k8s-operator-crds``.

Add or change a field here, run ``make generate``, and commit the regenerated
CRDs -- CI (generate-check) fails if they drift.
"""

from typing import ClassVar

from pydantic import BaseModel, ConfigDict, Field

GROUP = "airflow.drfaust92"
API_VERSION = "v1beta1"

_TEAM_NAME_DESC = (
    "Team for Airflow 3 multi-team mode. Requires multi-team mode enabled and "
    "the team to exist in Airflow, otherwise the API may reject the resource. "
    "Ignored on Airflow 2."
)


class SecretRef(BaseModel):
    """Reference to a key within a Kubernetes Secret."""

    model_config = ConfigDict(populate_by_name=True)

    name: str = Field(description="The name of the Kubernetes Secret.")
    key: str = Field(description="The key within the Secret.")


class SecretValue(BaseModel):
    """A value provided directly or sourced from a Kubernetes Secret."""

    model_config = ConfigDict(populate_by_name=True)

    value: str | None = Field(default=None, description="The direct value.")
    secretRef: SecretRef | None = Field(
        default=None, description="Reference to a Kubernetes Secret."
    )


class ConnectionSpec(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    crd: ClassVar[dict] = {
        "kind": "Connection",
        "plural": "connections",
        "singular": "connection",
        "short_names": ["conns", "conn"],
    }

    conn_type: str | None = Field(
        default=None, alias="connType", description="The connection type."
    )
    description: str | None = Field(
        default=None, description="The connection description."
    )
    host: str | None = Field(default=None, description="The connection host.")
    login: SecretValue | None = Field(
        default=None, description="The connection login (value or secretRef)."
    )
    password: SecretValue | None = Field(
        default=None, description="The connection password (value or secretRef)."
    )
    port: int | None = Field(
        default=None,
        description="The connection port.",
        json_schema_extra={"format": "int32"},
    )
    schema_: str | None = Field(
        default=None, alias="schema", description="The connection schema."
    )
    extra: str | None = Field(default=None, description="The connection extra field.")
    team_name: str | None = Field(
        default=None, alias="teamName", description=_TEAM_NAME_DESC
    )


class VariableSpec(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    crd: ClassVar[dict] = {
        "kind": "Variable",
        "plural": "variables",
        "singular": "variable",
        "short_names": ["vars", "var"],
        # Exactly one of value / secretRef must be set.
        "spec_one_of": [{"required": ["value"]}, {"required": ["secretRef"]}],
    }

    value: str | None = Field(
        default=None, description="The variable value (direct value)."
    )
    secretRef: SecretRef | None = Field(
        default=None,
        description="Reference to a Kubernetes Secret for the variable value.",
    )
    description: str | None = Field(
        default=None, description="The variable description."
    )
    team_name: str | None = Field(
        default=None, alias="teamName", description=_TEAM_NAME_DESC
    )


class PoolSpec(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    crd: ClassVar[dict] = {
        "kind": "Pool",
        "plural": "pools",
        "singular": "pool",
        "short_names": ["pls", "pl"],
    }

    slots: int = Field(
        description=(
            "The maximum number of slots that can be assigned to tasks. One job "
            "may occupy one or more slots."
        )
    )
    include_deferred: bool = Field(
        default=False,
        alias="includeDeferred",
        description="Whether to include deferred tasks in the pool.",
    )
    description: str | None = Field(default=None, description="The pool description.")
    team_name: str | None = Field(
        default=None, alias="teamName", description=_TEAM_NAME_DESC
    )


class ConfigMapRef(BaseModel):
    """Reference to a key within a Kubernetes ConfigMap."""

    model_config = ConfigDict(populate_by_name=True)

    name: str = Field(description="The name of the Kubernetes ConfigMap.")
    key: str = Field(
        description=(
            "The key within the ConfigMap: a plain-text DAG file in `data`, or "
            "a base64-encoded zip archive in `binaryData`."
        )
    )


class DagSourceUrl(BaseModel):
    """A DAG file or packaged-DAG zip downloaded from an http(s) URL."""

    model_config = ConfigDict(populate_by_name=True)

    url: str = Field(description="The http(s) URL of the DAG file or zip archive.")
    sha256: str | None = Field(
        default=None,
        description=(
            "Optional hex-encoded SHA-256 of the content. When set, downloads "
            "that do not match are rejected."
        ),
    )


class ObjectRef(BaseModel):
    """An existing gs:// or s3:// object to copy into the DAGs folder."""

    model_config = ConfigDict(populate_by_name=True)

    uri: str = Field(
        description="The gs://bucket/path or s3://bucket/path of the object."
    )


class DagSource(BaseModel):
    """Where the DAG file (or packaged-DAG zip) comes from. Exactly one of
    code / configMapRef / url / objectRef must be set."""

    model_config = ConfigDict(
        populate_by_name=True,
        json_schema_extra={
            "oneOf": [
                {"required": ["code"]},
                {"required": ["configMapRef"]},
                {"required": ["url"]},
                {"required": ["objectRef"]},
            ]
        },
    )

    code: str | None = Field(
        default=None, description="Inline Python source of a single DAG file."
    )
    configMapRef: ConfigMapRef | None = Field(
        default=None,
        description="Reference to a Kubernetes ConfigMap holding the DAG source.",
    )
    url: DagSourceUrl | None = Field(
        default=None, description="An http(s) URL to download the DAG source from."
    )
    objectRef: ObjectRef | None = Field(
        default=None,
        description="An existing object-store URI to copy the DAG source from.",
    )


class DagSpec(BaseModel):
    model_config = ConfigDict(populate_by_name=True)
    crd: ClassVar[dict] = {
        "kind": "Dag",
        "plural": "dags",
        "singular": "dag",
        "short_names": ["dgs", "dg"],
    }

    dag_id: str | None = Field(
        default=None,
        alias="dagId",
        description=(
            "The DAG ID in Airflow. Defaults to the resource name. Without "
            "`source`, DAGs cannot be created through the Airflow API -- they "
            "come from DAG files -- so this resource adopts an existing DAG "
            "and manages its paused state. Deleting the resource deletes the "
            "DAG's metadata/history in Airflow; the DAG reappears on the next "
            "parse if its file still exists."
        ),
    )
    is_paused: bool = Field(
        alias="isPaused", description="Whether the DAG is paused."
    )
    source: DagSource | None = Field(
        default=None,
        description=(
            "Optional DAG source to deliver to the Airflow DAGs folder "
            "(requires the operator's AIRFLOW_DAGS_URI to be configured). The "
            "content is uploaded as <dagId>.py, or <dagId>.zip when it is a "
            "packaged-DAG zip archive; for a zip, dagId names the primary DAG "
            "whose paused state is managed. Without source, the resource "
            "adopts a DAG that already exists in Airflow."
        ),
    )


# Order here drives the order the CRD files are generated in.
SPECS = [ConnectionSpec, PoolSpec, VariableSpec, DagSpec]
